def is_good_triple(x, y, z):
    """Checks if (x, y, z) is a good triple."""
    numerator = (x + 1)**y
    denominator = x**z + 1

    # Since x, y, z are positive integers, both numerator and denominator are positive integers.
    if denominator == 0:
        return False # Should not happen for positive x, z

    if numerator % denominator == 0:
        return True
    else:
        return False

# Search space: 1 <= x, y, z <= 5
good_triples = []
for x in range(1, 6):
    for y in range(1, 6):
        for z in range(1, 6):
            if is_good_triple(x, y, z):
                good_triples.append((x, y, z))

print("Good Triples (x<=5, y<=5, z<=5):")
for triple in good_triples:
    print(triple)

print(f"\nTotal good triples found: {len(good_triples)}")

